SELECT d.volume_id, d.document_id, dd.date_iso, substr(d.header,1,100) FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid LEFT JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE frus_documents MATCH '("Foreign Corrupt Practices" OR "questionable payments" OR "illegal payments" OR "corrupt practices" OR (Lockheed AND (bribe OR bribery OR payments OR corrupt)) OR "improper payments" OR "bribery of foreign")' AND d.is_front_matter=0 AND d.is_editorial_note=0 ORDER BY dd.date_iso LIMIT 150;
